_GET_INVOICES_BATCH: Final = "SELECT id, customer_id, number, status, currency, issued_on, due_on, notes, created_at, paid_at FROM invoices WHERE id = $1"


@dataclasses.dataclass(frozen=True, slots=True, kw_only=True)
class GetInvoicesBatchParams:
    id: UUID


async def get_invoices_batch(
    connection: psycopg.AsyncConnection[Any], rows: Iterable[GetInvoicesBatchParams]
) -> list[models.Invoice | None]:
    """Several invoices at once, each in the place of its id."""
    async with psycopg.AsyncRawCursor(connection, row_factory=tuple_row) as cur:
        await cur.executemany(
            _GET_INVOICES_BATCH, [(r.id,) for r in rows], returning=True
        )
        values: list[models.Invoice | None] = []
        async for result in cur.results():
            match await result.fetchmany(2):
                case [row]:
                    values.append(models.Invoice.from_row(row))
                case []:
                    values.append(None)
                case _:
                    raise models.MultipleRowsError
        return values


_LIST_INVOICE_NUMBERS_BATCH: Final = (
    "SELECT number FROM invoices WHERE customer_id = $1 ORDER BY number"
)


@dataclasses.dataclass(frozen=True, slots=True, kw_only=True)
class ListInvoiceNumbersBatchParams:
    customer_id: UUID


async def list_invoice_numbers_batch(
    connection: psycopg.AsyncConnection[Any],
    rows: Iterable[ListInvoiceNumbersBatchParams],
) -> list[list[str]]:
    async with psycopg.AsyncRawCursor(connection, row_factory=tuple_row) as cur:
        await cur.executemany(
            _LIST_INVOICE_NUMBERS_BATCH,
            [(r.customer_id,) for r in rows],
            returning=True,
        )
        return [
            [row[0] for row in await result.fetchall()]
            async for result in cur.results()
        ]


